int read_config(const char *path, struct config *out) {
    if (path == NULL || out == NULL)
        return -EINVAL;                        /* guard: before any acquisition */
    FILE *f = fopen(path, "r");
    if (f == NULL)
        return -errno;                         /* guard: nothing acquired yet */
    if (fseek(f, 0, SEEK_END) != 0) {          /* guard: release before exit */
        fclose(f);
        return -errno;
    }
    return config_parse(f, out);               /* happy path stays flat */
}

