errno_t do_something(void) {
    errno_t ret_val = NOERR;
    FILE *fin1 = fopen("a", "r");
    if (fin1 == NULL) return errno;                          /* guard: nothing held */
    FILE *fin2 = fopen("b", "r");
    if (fin2 == NULL) { ret_val = errno; goto FAIL_FIN2; }   /* guard -> cleanup */
    /* ... work ... */
    fclose(fin2);                                            /* success falls into chain */
FAIL_FIN2:
    fclose(fin1);
    return ret_val;                                          /* single exit, ordered release */
}
